def update_csv():
    csv_path = Path('data/processed/pending_dob_audit.csv')
    with open(csv_path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    updated_count = 0
    for r in rows:
        name = r['Name']
        if r['Status'] == 'PENDING' and name in audit_map:
            dob, url, status, notes = audit_map[name]
            r['DOB'] = dob
            r['Cricinfo_URL'] = url
            r['Status'] = status
            r['Notes'] = notes
            updated_count += 1

    fieldnames = ['Candidate_ID', 'Name', 'DOB', 'Cricinfo_URL', 'Status', 'Notes']
    with open(csv_path, 'w', encoding='utf-8', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)

    print(f"Updated {updated_count} rows in {csv_path}")

if __name__ == '__main__':
    update_csv()
